#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define THREAD_LOOP_COUNT 5

void *cancellable_task(void *arg) {
    int old_type;
    int rc;

    // 1. Ensure thread is cancelable
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    // 2. Set type to DEFERRED explicitly (though often default)
    rc = pthread_setcanceltype(PTHREAD_CANCEL_DEFERRED, &old_type);
    if (rc != 0) {
        fprintf(stderr, "Error setting cancel type: %s\n", strerror(rc));
        return NULL;
    }
    printf("Thread: Cancel type set to DEFERRED (Old type: %d)\n", old_type);

    // Loop without any explicit cancellation points
    for (int i = 0; i < THREAD_LOOP_COUNT; i++) {
        printf("Thread: Running critical iteration %d...\n", i);
        // Cancellation request remains pending here.
    }

    printf("Thread: Finished non-cancellation point work.\n");

    // 3. Introduce a cancellation point (sleep).
    // If canceled previously, the thread will terminate here.
    printf("Thread: Waiting at cancellation point (sleep(2))...\n");
    sleep(2); 

    printf("Thread: Should not be reached if main thread canceled successfully.\n");
    return NULL; 
}

int main() {
    pthread_t thread;
    int rc;

    // Create the thread
    rc = pthread_create(&thread, NULL, cancellable_task, NULL);
    if (rc != 0) {
        fprintf(stderr, "pthread_create error: %s\n", strerror(rc));
        return 1;
    }

    // Give the thread a moment to start and set its type
    usleep(100000); 

    // Send the cancellation request
    printf("Main: Sending cancellation request.\n");
    rc = pthread_cancel(thread);
    if (rc != 0) {
        fprintf(stderr, "pthread_cancel error: %s\n", strerror(rc));
        return 1;
    }

    // Join the thread to observe termination status
    void *res;
    rc = pthread_join(thread, &res);
    if (rc != 0) {
        fprintf(stderr, "pthread_join error: %s\n", strerror(rc));
        return 1;
    }

    if (res == PTHREAD_CANCELED) {
        printf("Main: Thread was successfully canceled at the sleep() point.\n");
    } else {
        printf("Main: Thread terminated normally (Error).\n");
    }

    return 0;
}
